<script setup lang="ts">import { onMounted, ref, watch } from "vue"; import { useRoute, useRouter } from "vue-router"; import type { PublishedGameSummary } from "@arcade/shared"; import { searchPortalGames } from "../services/api"; import { readFavorites, toggleFavorite, rememberRecent } from "../services/portalStorage"; import PortalSearchBar from "../components/portal/PortalSearchBar.vue"; import GameGrid from "../components/portal/GameGrid.vue"; import ContentStatePanel from "../components/portal/ContentStatePanel.vue";
const route = useRoute(); const router = useRouter(); const query = ref(String(route.query.q || "")); const games = ref<PublishedGameSummary[]>([]); const loading = ref(false); const error = ref(""); const favorites = ref<string[]>(readFavorites().values); async function search(): Promise<void> { query.value = String(route.query.q || ""); if (!query.value.trim()) { games.value = []; return; } loading.value = true; error.value = ""; try { games.value = (await searchPortalGames(query.value)).data; } catch { error.value = "搜索服务暂时不可用。"; } finally { loading.value = false; } } function favorite(slug: string): void { favorites.value = toggleFavorite(slug).values; } function play(slug: string): void { rememberRecent(slug); void router.push(`/zh/game/${slug}/play`); } watch(() => route.query.q, () => void search()); onMounted(() => { void search(); document.title = "搜索游戏｜星屿游廊"; });
</script><template><div class="portal-page"><section class="portal-page-heading"><span class="portal-eyebrow">SEARCH</span><h1>搜索游戏</h1><p>搜索结果仅用于发现内容，默认不纳入搜索引擎索引。</p></section><PortalSearchBar /><ContentStatePanel v-if="loading" kind="loading" title="正在搜索" message="正在匹配标题、描述、分类和标签。" /><ContentStatePanel v-else-if="error" kind="error" title="搜索失败" :message="error" action="重试" @action="search" /><ContentStatePanel v-else-if="!query.trim()" kind="empty" title="输入想找的内容" message="试试游戏名称、类型或标签。" /><ContentStatePanel v-else-if="!games.length" kind="empty" title="没有找到结果" message="换个关键词，或从分类入口开始探索。" action="浏览游戏大厅" @action="router.push('/zh/games')" /><GameGrid v-else :games="games" :favorites="favorites" @favorite="favorite" @play="play" /></div></template>
